package ai.decisionos.aside;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.Build;import org.json.*;import java.util.*;
/** OS alarms wake a reminder or a read-only portal refresh. All final actions remain user reviewed. */
public final class ScheduledWork extends BroadcastReceiver {
 static final String CHANNEL="nubi-scheduled-work";
 static boolean zoomUrl(String url){try{Uri u=Uri.parse(url);String h=u.getHost();return "https".equals(u.getScheme())&&u.getUserInfo()==null&&u.getPort()==-1&&h!=null&&(h.equals("zoom.us")||h.endsWith(".zoom.us")||h.equals("zoom.com")||h.endsWith(".zoom.com"))&&(u.getPath().startsWith("/j/")||u.getPath().startsWith("/my/")||u.getPath().startsWith("/wc/"));}catch(Exception e){return false;}}
 static PendingIntent alarm(Context c,String id){return PendingIntent.getBroadcast(c,0,new Intent(c,ScheduledWork.class).setAction(c.getPackageName()+".scheduled").setData(Uri.parse("nubi-work:"+id)),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void arm(Context c,String id){try(ScheduledWorkStore s=new ScheduledWorkStore(c)){JSONObject r=s.get(id);if(!r.optString("state").equals("SCHEDULED"))return;AlarmManager manager=c.getSystemService(AlarmManager.class);long due=Math.max(System.currentTimeMillis()+500,r.optLong("due_at"));boolean exact=Build.VERSION.SDK_INT<31||manager.canScheduleExactAlarms();try{if(exact)manager.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,due,alarm(c,id));else manager.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,due,alarm(c,id));}catch(SecurityException revoked){exact=false;manager.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,due,alarm(c,id));}s.metadata(id,"precision",exact?"exact_permission_granted":"inexact_os_may_delay");}}
 static void cancel(Context c,String id){try(ScheduledWorkStore s=new ScheduledWorkStore(c)){JSONObject r=s.get(id);s.state(id,r.optString("state"),"CANCELLED","사용자가 예약을 취소했어요");}c.getSystemService(AlarmManager.class).cancel(alarm(c,id));c.getSystemService(NotificationManager.class).cancel(id,0);}
 static void restore(Context c){restore(c,false);}
 static void restore(Context c,boolean systemRestart){ChatWork.schedule(c);try(ScheduledWorkStore s=new ScheduledWorkStore(c)){for(JSONObject r:s.list()){if(r.optString("state").equals("REFRESH_QUEUED")){String id=r.optString("id");if(systemRestart){if(!CampusNoticeMonitor.scheduleNow(c))s.state(id,"REFRESH_QUEUED","FAILED","재시작 뒤 학교 조회를 예약하지 못했어요. 다시 요청해 주세요.");}else if(System.currentTimeMillis()-r.optLong("fired_at")>300000)s.state(id,"REFRESH_QUEUED","FAILED","조회 결과가 5분 안에 도착하지 않았어요. 중복 실행을 피하려고 중단 상태로 보관했어요. 다시 요청해 주세요.");r=s.get(id);}if(!r.optString("repeat_rule").isEmpty()&&!r.optString("state").equals("SCHEDULED")){try{String next=s.repeatNext(r.optString("id"),System.currentTimeMillis());if(!next.isEmpty())arm(c,next);}catch(Exception e){android.util.Log.e("NubiSchedule","repeat restore failed");}}if(r.optString("state").equals("SCHEDULED"))arm(c,r.optString("id"));else if(Arrays.asList("READY","RESULT_READY","FAILED").contains(r.optString("state")))notify(c,r);}}}
 static void fire(Context c,String id){try(ScheduledWorkStore s=new ScheduledWorkStore(c)){if(!s.claim(id,System.currentTimeMillis()))return;try{String next=s.repeatNext(id,System.currentTimeMillis());if(!next.isEmpty())arm(c,next);}catch(Exception e){android.util.Log.e("NubiSchedule","repeat creation failed: "+e.getClass().getSimpleName());}}ChatWork.enqueue(c,id);}
 static void refreshFinished(Context c,List<String> ids,String error,String evidence){try(ScheduledWorkStore s=new ScheduledWorkStore(c)){for(String id:ids){if(s.state(id,"REFRESH_QUEUED",error==null?"RESULT_READY":"FAILED",error==null?evidence:error)){JSONObject row=s.get(id);if(error==null)SchoolChatWork.publish(c,"portal",id,row.optString("title"),evidence,"https://portal.unist.ac.kr/",java.time.Instant.now().toString());notify(c,row);}}}}
 static void notify(Context c,JSONObject row){String id=row.optString("id");if(id.isEmpty())return;NotificationManager nm=c.getSystemService(NotificationManager.class);android.app.Activity visible=NubiApplication.foreground.get();if(visible instanceof GoalAgentActivity&&!visible.isFinishing()){nm.cancel(id,0);try(ScheduledWorkStore store=new ScheduledWorkStore(c)){store.metadata(id,"notification","home_conversation_visible");}return;}nm.createNotificationChannel(new NotificationChannel(CHANNEL,"누비가 맡은 일 · 기한 알림",NotificationManager.IMPORTANCE_HIGH));String title=row.optString("title"),state=row.optString("state"),detail=row.optString("detail");if(detail.isEmpty())detail="약속한 시간이 됐어요. 눌러서 담당 누비에게 돌아가요.";Intent intent=new Intent(c,GoalAgentActivity.class).putExtra("goal_id",row.optString("goal_id")).putExtra("scheduled_work_id",id).setData(Uri.parse("nubi-work:"+id)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);PendingIntent tap=PendingIntent.getActivity(c,0,intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);boolean allowed=nm.areNotificationsEnabled();try{if(allowed)nm.notify(id,0,new Notification.Builder(c,CHANNEL).setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle(title).setContentText(detail).setStyle(new Notification.BigTextStyle().bigText(detail)).setVisibility(Notification.VISIBILITY_PRIVATE).setContentIntent(tap).setAutoCancel(true).setOnlyAlertOnce(true).build());}catch(SecurityException denied){allowed=false;}try(ScheduledWorkStore s=new ScheduledWorkStore(c)){s.metadata(id,"notification",allowed?"posted":"permission_blocked_home_available");}}
 @Override public void onReceive(Context c,Intent intent){String action=intent.getAction();if(Intent.ACTION_BOOT_COMPLETED.equals(action)||Intent.ACTION_MY_PACKAGE_REPLACED.equals(action)||Intent.ACTION_TIME_CHANGED.equals(action)||Intent.ACTION_TIMEZONE_CHANGED.equals(action)||AlarmManager.ACTION_SCHEDULE_EXACT_ALARM_PERMISSION_STATE_CHANGED.equals(action)){restore(c,Intent.ACTION_BOOT_COMPLETED.equals(action)||Intent.ACTION_MY_PACKAGE_REPLACED.equals(action));return;}Uri data=intent.getData();if(data!=null&&"nubi-work".equals(data.getScheme()))fire(c,data.getSchemeSpecificPart());}
 static String label(JSONObject r){String state=r.optString("state");if(state.equals("CHAT_QUEUED"))return "대화방에서 실행 대기";if(state.equals("CHAT_RUNNING"))return "대화방에서 작업 중";if(state.equals("RESULT_READY"))return "실제 조회 결과 도착";if(state.equals("FAILED"))return "확인 필요";if(state.equals("REFRESH_QUEUED"))return "학교 공지 조회 대기";if(state.equals("READY"))return "지금 확인할 일";return r.optString("precision").startsWith("exact")?"예약됨":"예약됨 · OS 지연 가능";}
}
